# Combine all data
all_data = pd.concat(dfs.values(), ignore_index=True)
print(f"\nCombined shape: {all_data.shape}")
print(f"\nAll columns: {list(all_data.columns)}")

# Find throughput column
throughput_col = None
for c in all_data.columns:
    if 'throughput' in c.lower() or 'job' in c.lower():
        throughput_col = c
        break
